import { UploadClient } from '@uploadcare/upload-client'

const PUBLIC_KEY = process.env.EXPO_PUBLIC_UPLOADCARE_PUBLIC_KEY

export const uc = new UploadClient({ publicKey: String(PUBLIC_KEY) })

export async function uploadOne(
	uri: string,
	fileName = 'image.jpg',
	mime = 'image/jpeg'
) {
	const fileInfo = await uc.uploadFile({ uri, name: fileName, type: mime })
	return fileInfo.cdnUrl!
}

export async function uploadMany(uris: string[]) {
	const uploads = uris.map((u) => uploadOne(u))
	return Promise.all(uploads)
}
